import { test } from 'node:test';
import assert from 'node:assert/strict';
import { inRange, rangesIntersect } from './daterange.mjs';

test('inRange: strictly inside range is true', () => {
  assert.equal(inRange('2026-06-15', '2026-06-01', '2026-07-01'), true);
});

test('inRange: date equal to start is true (inclusive start)', () => {
  // kills M1 (>= -> >)
  assert.equal(inRange('2026-06-01', '2026-06-01', '2026-07-01'), true);
});

test('inRange: date equal to end is false (exclusive end)', () => {
  // kills M2 (< -> <=)
  assert.equal(inRange('2026-07-01', '2026-06-01', '2026-07-01'), false);
});

test('inRange: date before start is false even though before end', () => {
  // kills M3 (&& -> ||)
  assert.equal(inRange('2026-05-01', '2026-06-01', '2026-07-01'), false);
});

test('inRange: date after end is false', () => {
  assert.equal(inRange('2026-08-01', '2026-06-01', '2026-07-01'), false);
});

test('rangesIntersect: overlapping ranges intersect', () => {
  assert.equal(
    rangesIntersect('2026-01-01', '2026-02-01', '2026-01-15', '2026-03-01'),
    true
  );
});

test('rangesIntersect: contained range intersects', () => {
  // kills M6 (bStart < aEnd -> bStart < aStart)
  assert.equal(
    rangesIntersect('2026-01-01', '2026-12-31', '2026-06-01', '2026-07-01'),
    true
  );
});

test('rangesIntersect: adjacent sharing endpoint (b starts at aEnd) must NOT intersect', () => {
  // kills M5 (bStart < aEnd -> <=)
  assert.equal(
    rangesIntersect('2026-01-01', '2026-02-01', '2026-02-01', '2026-03-01'),
    false
  );
});

test('rangesIntersect: adjacent sharing endpoint (a starts at bEnd) must NOT intersect', () => {
  // kills M4 (aStart < bEnd -> <=)
  assert.equal(
    rangesIntersect('2026-02-01', '2026-03-01', '2026-01-01', '2026-02-01'),
    false
  );
});

test('rangesIntersect: fully disjoint ranges do not intersect', () => {
  assert.equal(
    rangesIntersect('2026-01-01', '2026-02-01', '2026-05-01', '2026-06-01'),
    false
  );
});

