#!/usr/bin/env node
// Mutate-and-run harness: applies each mutant via string replacement,
// runs node --test against the temp copy, prints a results table.
import { spawnSync } from 'node:child_process';
import { mkdtempSync, writeFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

const SRC = new URL('./daterange.mjs', import.meta.url).pathname;
const TEST = new URL('./daterange.test.mjs', import.meta.url).pathname;

const MUTANTS = [
  { id: 'M1', desc: "inRange: '>=' -> '>'", from: 'dateIso >= startIso', to: 'dateIso > startIso' },
  { id: 'M2', desc: 'inRange: < -> <= (end)', from: 'dateIso < endIso', to: 'dateIso <= endIso' },
  { id: 'M3', desc: 'inRange: && -> ||', from: 'dateIso >= startIso && dateIso < endIso', to: 'dateIso >= startIso || dateIso < endIso' },
  { id: 'M4', desc: 'rangesIntersect: aStart < bEnd -> <=', from: 'aStart < bEnd', to: 'aStart <= bEnd' },
  { id: 'M5', desc: 'rangesIntersect: bStart < aEnd -> <=', from: 'bStart < aEnd', to: 'bStart <= aEnd' },
  { id: 'M6', desc: 'rangesIntersect: bStart < aEnd -> bStart < aStart', from: 'bStart < aEnd', to: 'bStart < aStart' },
];

function runTests(dir) {
  const r = spawnSync('node', ['--test', TEST], {
    cwd: dir,
    encoding: 'utf8',
    env: { ...process.env },
  });
  const failed = /fail \d+/.exec(r.stdout)?.[0] ?? '?';
  const passed = /pass \d+/.exec(r.stdout)?.[0] ?? '?';
  return { ok: r.status === 0, passed, failed };
}

const srcCode = (await import('node:fs/promises')).readFile(SRC, 'utf8');

// Pristine run
const pristineDir = mkdtempSync(join(tmpdir(), 'pristine-'));
writeFileSync(join(pristineDir, 'daterange.mjs'), await srcCode);
writeFileSync(join(pristineDir, 'daterange.test.mjs'), await import('node:fs/promises').then(f => f.readFile(TEST, 'utf8')));
// test file imports './daterange.mjs' relative to itself; copy it into temp dir
rmSync(pristineDir, { recursive: true, force: true });

async function makeSandbox(code) {
  const dir = mkdtempSync(join(tmpdir(), 'mut-'));
  writeFileSync(join(dir, 'daterange.mjs'), code);
  const testCode = await (await import('node:fs/promises')).readFile(TEST, 'utf8');
  writeFileSync(join(dir, 'daterange.test.mjs'), testCode);
  return dir;
}

const rows = [];
let killed = 0;
for (const m of MUTANTS) {
  const code = (await srcCode).replace(m.from, m.to);
  if (code === (await srcCode)) {
    rows.push({ id: m.id, desc: m.desc, result: 'NOT-APPLIED' });
    continue;
  }
  const dir = await makeSandbox(code);
  const { ok, passed, failed } = runTests(dir);
  rmSync(dir, { recursive: true, force: true });
  if (!ok) killed++;
  rows.push({ id: m.id, desc: m.desc, result: ok ? 'SURVIVED' : `KILLED (${passed}, ${failed})` });
}

// Pristine verification
const pDir = await makeSandbox(await srcCode);
const pristine = runTests(pDir);
rmSync(pDir, { recursive: true, force: true });

console.log('┌──────┬──────────────────────────────────────────┬───────────────────────┐');
console.log('│ ID   │ Mutant                                   │ Result                │');
console.log('├──────┼──────────────────────────────────────────┼───────────────────────┤');
for (const r of rows) {
  console.log(`│ ${r.id.padEnd(4)} │ ${r.desc.padEnd(40)} │ ${r.result.padEnd(21)} │`);
}
console.log('└──────┴──────────────────────────────────────────┴───────────────────────┘');
console.log(`\nPristine tests: ${pristine.ok ? 'GREEN ✓' : 'RED ✗'} (${pristine.passed}, ${pristine.failed})`);
console.log(`Mutants killed: ${killed}/${MUTANTS.length}`);
if (killed !== MUTANTS.length || !pristine.ok) {
  console.log('FAIL');
  process.exit(1);
}
console.log('PASS: all mutants killed and pristine suite is green.');

